const email = $json;
const subject = String(email.subject ?? email.Subject ?? email.headers?.subject ?? '');
const titleMatch = subject.match(/\b(Sprint Planning|Sprint Estimating)\b/i);
const html = [email.textHtml, email.textAsHtml, email.html, email.textPlain, email.text, email.snippet].filter(Boolean).join('\n');
const docMatch = html.match(/(?:https?:\/\/)?docs\.google\.com\/document\/d\/([a-zA-Z0-9_-]+)/i);
const docId = docMatch?.[1] ?? email.docId ?? null;
const receivedAt = email.internalDate ?? email.date ?? new Date().toISOString();
return [{ json: {
  subject,
  title: titleMatch?.[1] ?? null,
  meetingDate: receivedAt,
  docId,
  docUrl: docId ? `https://docs.google.com/document/d/${docId}/edit` : null,
  emailId: email.id ?? email.messageId ?? null,
  sourceEmail: email,
} }];

const identity = $('Extract Meeting Identity').item.json;
const staticData = $getWorkflowStaticData('global');
staticData.meetingDocs = staticData.meetingDocs || {};
const prior = identity.docId ? staticData.meetingDocs[identity.docId] : null;
if (prior) {
  return [{ json: { ...identity, route: 'duplicate', calendarVerified: false, reason: `Doc ID already processed with status ${prior.status}.` } }];
}
if (!identity.title || !identity.docId) {
  return [{ json: { ...identity, route: 'ignore', calendarVerified: false, reason: 'Gemini subject is not Sprint Planning/Estimating or the Google Doc ID is missing.' } }];
}
staticData.meetingDocs[identity.docId] = { status: 'processing', startedAt: Date.now(), title: identity.title };
return [{ json: { ...identity, route: 'accept', calendarVerified: false, meetingIdentityVerified: true, reason: 'Accepted from filtered Gemini meeting identity and Doc ID.' } }];
